CREATE TABLE IF NOT EXISTS plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(50) NOT NULL, price_cents INT UNSIGNED NOT NULL DEFAULT 0, customer_limit INT UNSIGNED NOT NULL, deal_limit INT UNSIGNED NOT NULL, user_limit INT UNSIGNED NOT NULL, task_limit INT UNSIGNED NOT NULL);
INSERT IGNORE INTO plans(code,name,price_cents,customer_limit,deal_limit,user_limit,task_limit) VALUES ('free','Free',0,5,5,1,5),('pro','Pro',2990,100,100,3,100),('premium','Premium',4990,500,500,5,500);
CREATE TABLE IF NOT EXISTS companies (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,owner_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(status));
CREATE TABLE IF NOT EXISTS company_subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id INT UNSIGNED NOT NULL,plan_code VARCHAR(20) NOT NULL DEFAULT 'free',status ENUM('active','expired') NOT NULL DEFAULT 'active',assigned_by INT UNSIGNED NULL,expires_at DATETIME NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY(company_id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('global_admin','owner','member') NOT NULL DEFAULT 'member',status ENUM('active','suspended') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),INDEX(company_id));
CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,organization VARCHAR(160) NULL,source VARCHAR(80) NULL,notes TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),INDEX(company_id));
CREATE TABLE IF NOT EXISTS deals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id INT UNSIGNED NOT NULL,customer_id INT UNSIGNED NULL,title VARCHAR(180) NOT NULL,value_cents INT UNSIGNED NOT NULL DEFAULT 0,stage ENUM('new','contacted','qualified','proposal','negotiation','won','lost') NOT NULL DEFAULT 'new',expected_date DATE NULL,notes TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,INDEX(company_id,stage));
CREATE TABLE IF NOT EXISTS tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id INT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,due_date DATE NULL,status ENUM('pending','done') NOT NULL DEFAULT 'pending',customer_id INT UNSIGNED NULL,deal_id INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),INDEX(company_id,status,due_date));
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,company_id INT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NULL,entity_id INT UNSIGNED NULL,details TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
